import json,datetime
for p in ['products/research/se-shopify-csv-variants.json','products/research/shopify-community-search.json']:
  raw=open(p,encoding='utf-8',errors='replace').read()
  print('==',p,len(raw))
  try: d=json.loads(raw)
  except Exception as e: print('notjson',e,raw[:300]); continue
  print('keys',list(d)[:10])
  for it in d.get('items',[])[:30]:
    print(datetime.datetime.utcfromtimestamp(it['creation_date']).date(),it.get('is_answered'),it.get('answer_count'),it['link'],'|',it['title'][:100])
  for t in d.get('topics',[])[:40]:
    print(t.get('created_at','')[:10],t.get('id'),t.get('posts_count'),t.get('has_accepted_answer'),'|',t.get('title','')[:100])
  print('posts',len(d.get('posts',[])),'grouped',d.get('grouped_search_result',{}).get('more_full_page_results'))
